SELECT molecule_dictionary.chembl_id, molecule_dictionary.pref_name, compound_structures.canonical_smiles, molecule_dictionary.max_phase, drug_mechanism.mechanism_of_action, drug_mechanism.action_type, target_dictionary.chembl_id AS target_chembl_id, target_dictionary.pref_name AS target_name FROM molecule_dictionary JOIN drug_mechanism ON molecule_dictionary.molregno = drug_mechanism.molregno JOIN target_dictionary ON drug_mechanism.tid = target_dictionary.tid JOIN compound_structures ON molecule_dictionary.molregno = compound_structures.molregno WHERE molecule_dictionary.max_phase = 4 AND drug_mechanism.action_type = 'BLOCKER' ORDER BY molecule_dictionary.chembl_id ASC, molecule_dictionary.pref_name ASC, compound_structures.canonical_smiles ASC, molecule_dictionary.max_phase ASC, drug_mechanism.mechanism_of_action ASC, drug_mechanism.action_type ASC, target_dictionary.chembl_id ASC, target_dictionary.pref_name ASC
